-- Expense red-flag tests. Flags per line (order): RND WKD OUTL DUP SELFP NODESC NOATT THR REV; score weights 1,1,3,2,1,1,1,2,1.
-- Part S = monthly counts per account; part L = top-scoring lines. UNION ALL keeps the output large enough to be
-- saved to a file by the MCP host (then parse it from the file instead of re-typing).
SELECT 'S'||ACCOUNT_NO||'|'||LISTAGG(YM||':'||N||':'||RND||':'||WKD||':'||OUTL||':'||DUP||':'||SELFP||':'||NODESC||':'||NOATT||':'||THR||':'||REV,',') WITHIN GROUP (ORDER BY YM) R
FROM (SELECT ACCOUNT_NO, TO_CHAR(VM_DATE,'YYMM') YM, COUNT(*) N, SUM(RND) RND, SUM(WKD) WKD, SUM(OUTL) OUTL, SUM(DUP) DUP, SUM(SELFP) SELFP, SUM(NODESC) NODESC, SUM(NOATT) NOATT, SUM(THR) THR, SUM(REV) REV
 FROM ({FLAGS}) GROUP BY ACCOUNT_NO, TO_CHAR(VM_DATE,'YYMM')) GROUP BY ACCOUNT_NO
UNION ALL
SELECT 'L'||ACCOUNT_NO||'~'||VOUCHER_NO||'~'||TO_CHAR(VM_DATE,'YYYY-MM-DD')||'~'||DR||'~'||CR||'~'||VM_TYPE||'~'||ENTRY_USER||'~'||ENTRY_NAME||'~'||POSTING_NAME||'~'||SUBSTR(SUB_ACCOUNT_ARB_NAME,1,40)||'~'||REPLACE(REPLACE(SUBSTR(DESCRIPTION,1,100),'~',' '),'|','/')||'~'||RND||WKD||OUTL||DUP||SELFP||NODESC||NOATT||THR||REV||'~'||SC R
FROM (SELECT X.*, (RND+WKD+3*OUTL+2*DUP+SELFP+NODESC+NOATT+2*THR+REV) SC, ROW_NUMBER() OVER (ORDER BY (RND+WKD+3*OUTL+2*DUP+SELFP+NODESC+NOATT+2*THR+REV) DESC, DR+CR DESC) RN FROM ({FLAGS}) X) WHERE RN<={TOPN};
